def make_skill(body: str, name: str = "example-skill") -> str:
    return textwrap.dedent(
        f"""\
        ---
        name: {name}
        description: Example skill.
        ---

        {body.strip()}
        """
    )


@contextlib.contextmanager
def temporary_repo(
    skill_packages: dict[str, dict[str, str]],
    *,
    command_files: dict[str, str] | None = None,
    settings_files: dict[str, str] | None = None,
    codex_skill_names: tuple[str, ...] = (),
    existing_hooks_json: str | None = None,
):
    with tempfile.TemporaryDirectory() as tmpdir:
        root = Path(tmpdir)
        source_skills_dir = root / ".claude" / "skills"
        source_commands_dir = root / ".claude" / "commands"
        target_skills_dir = root / ".codex" / "skills"
        claude_agents_dir = root / ".claude" / "agents"
        codex_agents_dir = root / ".codex" / "agents"
        hooks_path = root / ".codex" / "hooks.json"

        source_skills_dir.mkdir(parents=True)
        source_commands_dir.mkdir(parents=True)
        target_skills_dir.mkdir(parents=True)
        claude_agents_dir.mkdir(parents=True)
        codex_agents_dir.mkdir(parents=True)

        for name, files in skill_packages.items():
            skill_dir = source_skills_dir / name
            skill_dir.mkdir(parents=True, exist_ok=True)
            for relative_path, content in files.items():
                file_path = skill_dir / relative_path
                file_path.parent.mkdir(parents=True, exist_ok=True)
                file_path.write_text(textwrap.dedent(content).lstrip(), encoding="utf-8")

        for relative_path, content in (command_files or {}).items():
            command_path = source_commands_dir / relative_path
            command_path.parent.mkdir(parents=True, exist_ok=True)
            command_path.write_text(textwrap.dedent(content).lstrip(), encoding="utf-8")

        for relative_path, content in (settings_files or {}).items():
            settings_path = root / ".claude" / relative_path
            settings_path.parent.mkdir(parents=True, exist_ok=True)
            settings_path.write_text(textwrap.dedent(content).lstrip(), encoding="utf-8")

        for name in codex_skill_names:
            codex_skill_dir = target_skills_dir / name
            codex_skill_dir.mkdir(parents=True, exist_ok=True)
            (codex_skill_dir / "SKILL.md").write_text("# Codex skill\n", encoding="utf-8")

        if existing_hooks_json is not None:
            hooks_path.parent.mkdir(parents=True, exist_ok=True)
            hooks_path.write_text(existing_hooks_json, encoding="utf-8")

        with contextlib.ExitStack() as stack:
            stack.enter_context(patch.object(MODULE, "REPO_ROOT", root))
            stack.enter_context(patch.object(MODULE, "SOURCE_SKILLS_DIR", source_skills_dir))
            stack.enter_context(patch.object(MODULE, "SOURCE_COMMANDS_DIR", source_commands_dir))
            stack.enter_context(patch.object(MODULE, "TARGET_SKILLS_DIR", target_skills_dir))
            stack.enter_context(patch.object(MODULE, "SOURCE_AGENTS_DIR", claude_agents_dir))
            stack.enter_context(patch.object(MODULE, "TARGET_AGENTS_DIR", codex_agents_dir))
            stack.enter_context(patch.object(MODULE, "TARGET_HOOKS_PATH", hooks_path))
            yield root


class SkillMigrationClassifierTests(unittest.TestCase):
    def test_web_primitives_use_current_codex_mappings_in_both_tables(self) -> None:
        text = "Call WebSearch first, then WebFetch for the source page.\n"

        expected = (
            "Call # CODEX: use web_search; cached by default, "
            "live via --search when freshness matters first, "
            "then # CODEX: no direct WebFetch primitive; use shell/curl "
            "or HTTP client with network access "
            "for the source page.\n"
        )
        self.assertEqual(MODULE.apply_primitive_mappings(text), expected)
        self.assertEqual(SHARED_PRIMITIVES.apply_primitive_mappings(text), expected)

    def test_webfetch_mapping_does_not_imply_direct_codex_primitive(self) -> None:
        replacements = dict(MODULE.PRIMITIVE_REPLACEMENTS)
        shared_replacements = dict(SHARED_PRIMITIVES.PRIMITIVE_REPLACEMENTS)

        self.assertIn("no direct WebFetch primitive", replacements["WebFetch"])
        self.assertEqual(replacements["WebFetch"], shared_replacements["WebFetch"])

    def test_web_mapping_table_lines_are_not_rewritten(self) -> None:
        text = "| `WebSearch` -> `search` | Use WebFetch after it |\n"

        self.assertEqual(MODULE.apply_primitive_mappings(text), text)
        self.assertEqual(SHARED_PRIMITIVES.apply_primitive_mappings(text), text)

    def test_redirected_skill_short_circuits_explicit_analysis(self) -> None:
        skill_packages = {
            "example-history-skill": {
                "SKILL.md": """\
                    ---
                    name: example-history-skill
                    description: "REDIRECTED to pattern-miner (mode:history)."
                    ---

                    # example-history-skill — REDIRECTED

                    **Replacement**: Use `pattern-miner` with `source:history` for commit history mining.
                """,
                "references/IMPLEMENTATION.md": """\
                    # Implementation

                    Task({
                      description: "legacy task",
                    })
                """,
            }
        }

        with temporary_repo(skill_packages):
            stdout = io.StringIO()
            with contextlib.redirect_stdout(stdout):
                result = MODULE.migrate_skill(
                    "example-history-skill",
                    dry_run=True,
                    analysis_only=True,
                )

        output = stdout.getvalue()
        self.assertEqual(result.status, "REDIRECTED")
        self.assertIn("example-history-skill: REDIRECTED", output)
        self.assertIn("replacement: Use `pattern-miner` with `source:history`", output)
        self.assertNotIn("inline Claude Task() site", output)

