class CommandConversionTests(unittest.TestCase):
    def test_converts_simple_claude_command_to_command_skill(self) -> None:
        with temporary_repo({}, command_files={"deploy.md": "Run deployment\n"}) as root:
            report = MODULE.migrate_project_surfaces(dry_run=False, analysis_only=False)

            output = root / ".codex" / "skills" / "command-deploy" / "SKILL.md"
            text = output.read_text(encoding="utf-8")

        self.assertEqual(report.commands[0].target_skill, "command-deploy")
        self.assertEqual(report.commands[0].status, "manual-review-required")
        self.assertEqual(MODULE._surface_summary(report)["manual_review_items"], 1)
        self.assertIn("name: command-deploy", text)
        self.assertIn("## Command Template", text)
        self.assertIn("## MANUAL MIGRATION REQUIRED", text)

    def test_converts_nested_command_with_stable_name(self) -> None:
        with temporary_repo({}, command_files={"db/migrate.md": "Run db migration\n"}) as root:
            MODULE.migrate_project_surfaces(dry_run=False, analysis_only=False)

            output = root / ".codex" / "skills" / "command-db-migrate" / "SKILL.md"
            self.assertTrue(output.exists())

    def test_command_uses_frontmatter_description(self) -> None:
        with temporary_repo(
            {},
            command_files={
                "release.md": """\
                    ---
                    description: Ship a release.
                    ---

                    Run release.
                """
            },
        ) as root:
            MODULE.migrate_project_surfaces(dry_run=False, analysis_only=False)
            text = (root / ".codex" / "skills" / "command-release" / "SKILL.md").read_text(
                encoding="utf-8"
            )

        self.assertIn("description: Ship a release.", text)

    def test_existing_user_command_skill_blocks_live_write(self) -> None:
        with temporary_repo(
            {},
            command_files={"deploy.md": "Run deployment\n"},
            codex_skill_names=("command-deploy",),
        ) as root:
            output = root / ".codex" / "skills" / "command-deploy" / "SKILL.md"
            before = output.read_text(encoding="utf-8")
            report = MODULE.migrate_project_surfaces(dry_run=False, analysis_only=False)
            after = output.read_text(encoding="utf-8")

        self.assertEqual(before, "# Codex skill\n")
        self.assertEqual(after, before)
        self.assertEqual(report.commands[0].status, "target-collision")
        self.assertIn("merge manually", "\n".join(report.commands[0].manual_review_reasons))

    def test_command_placeholder_caveats(self) -> None:
        with temporary_repo({}, command_files={"test.md": "Run $ARGUMENTS then inspect $1\n"}):
            report = MODULE.migrate_project_surfaces(dry_run=True, analysis_only=False)

        reasons = "\n".join(report.commands[0].manual_review_reasons)
        self.assertIn("argument placeholders", reasons)
        self.assertIn("positional placeholders", reasons)
        self.assertEqual(report.commands[0].status, "manual-review-required")

    def test_command_template_shell_file_and_frontmatter_caveats(self) -> None:
        with temporary_repo(
            {},
            command_files={
                "service.md": """\
                    ---
                    description: Service command.
                    allowed-tools: Bash
                    ---

                    Check {{service}}, run !`git status`, and read @docs/runbook.md plus @path.
                """
            },
        ):
            report = MODULE.migrate_project_surfaces(dry_run=True, analysis_only=False)

        reasons = "\n".join(report.commands[0].manual_review_reasons)
        self.assertIn("template variables", reasons)
        self.assertIn("shell interpolation", reasons)
        self.assertIn("@ files", reasons)
        self.assertIn("allowed-tools", reasons)

    def test_command_slug_collision_uses_hash_suffix(self) -> None:
        with temporary_repo(
            {},
            command_files={
                "foo_bar.md": "Run A\n",
                "foo/bar.md": "Run B\n",
            },
        ):
            report = MODULE.migrate_project_surfaces(dry_run=True, analysis_only=False)

        names = sorted(command.target_skill for command in report.commands)
        self.assertEqual(len(names), 2)
        self.assertTrue(all(name.startswith("command-foo-bar-") for name in names))
        self.assertTrue(all(command.collision_suffix_applied for command in report.commands))


class HookConversionTests(unittest.TestCase):
    def test_converts_supported_stop_hook_to_codex_hooks_json(self) -> None:
        with temporary_repo(
            {},
            settings_files={
                "settings.json": json.dumps(
                    {"hooks": {"Stop": [{"hooks": [{"type": "command", "command": "npm test"}]}]}}
                )
            },
        ) as root:
            report = MODULE.migrate_project_surfaces(dry_run=False, analysis_only=False)
            payload = json.loads((root / ".codex" / "hooks.json").read_text(encoding="utf-8"))

        self.assertEqual(payload["_generated_by"], MODULE.GENERATED_HOOKS_MARKER)
        self.assertEqual(payload["hooks"]["Stop"][0]["hooks"][0]["command"], "npm test")
        self.assertEqual(report.hooks[0].status, "converted-hook-review-required")

    def test_converts_pretooluse_matcher(self) -> None:
        with temporary_repo(
            {},
            settings_files={
                "settings.json": json.dumps(
                    {
                        "hooks": {
                            "PreToolUse": [
                                {
                                    "matcher": "Bash",
                                    "hooks": [{"command": "npm run lint", "timeoutSec": 30}],
                                }
                            ]
                        }
                    }
                )
            },
        ) as root:
            MODULE.migrate_project_surfaces(dry_run=False, analysis_only=False)
            payload = json.loads((root / ".codex" / "hooks.json").read_text(encoding="utf-8"))

        self.assertEqual(payload["hooks"]["PreToolUse"][0]["matcher"], "Bash")
        self.assertEqual(payload["hooks"]["PreToolUse"][0]["hooks"][0]["timeout"], 30)

    def test_omits_stop_matcher_and_reports_review(self) -> None:
        with temporary_repo(
            {},
            settings_files={
                "settings.json": json.dumps(
                    {
                        "hooks": {
                            "Stop": [
                                {"matcher": "Bash", "hooks": [{"command": "npm test"}]}
                            ]
                        }
                    }
                )
            },
        ) as root:
            report = MODULE.migrate_project_surfaces(dry_run=False, analysis_only=False)
            payload = json.loads((root / ".codex" / "hooks.json").read_text(encoding="utf-8"))

        self.assertNotIn("matcher", payload["hooks"]["Stop"][0])
        self.assertIn("matcher omitted", "\n".join(report.hooks[0].manual_review_reasons))

    def test_timeout_precedence_reports_when_both_timeout_fields_exist(self) -> None:
        with temporary_repo(
            {},
            settings_files={
                "settings.json": json.dumps(
                    {
                        "hooks": {
                            "PostToolUse": [
                                {
                                    "matcher": "Bash",
                                    "hooks": [{"command": "npm test", "timeout": 10, "timeoutSec": 30}],
                                }
                            ]
                        }
                    }
                )
            },
        ) as root:
            report = MODULE.migrate_project_surfaces(dry_run=False, analysis_only=False)
            payload = json.loads((root / ".codex" / "hooks.json").read_text(encoding="utf-8"))

        self.assertEqual(payload["hooks"]["PostToolUse"][0]["hooks"][0]["timeout"], 10)
        self.assertIn("timeoutSec", "\n".join(report.hooks[0].manual_review_reasons))

    def test_non_command_and_async_hooks_are_skipped_and_reported(self) -> None:
        with temporary_repo(
            {},
            settings_files={
                "settings.json": json.dumps(
                    {
                        "hooks": {
                            "Stop": [
                                {
                                    "hooks": [
                                        {"type": "prompt", "command": "mutate prompt"},
                                        {"type": "command", "command": "npm test", "async": True},
                                    ]
                                }
                            ]
                        }
                    }
                )
            },
        ):
            report = MODULE.migrate_project_surfaces(dry_run=True, analysis_only=False)

        self.assertEqual(report.hooks, [])
        self.assertEqual(len(report.unsupported_hooks), 2)

    def test_generated_hooks_json_refreshes_on_second_live_batch_run(self) -> None:
        settings = {
            "settings.json": json.dumps(
                {"hooks": {"Stop": [{"hooks": [{"command": "npm test"}]}]}}
            )
        }
        with temporary_repo({}, settings_files=settings) as root:
            first_report = MODULE.migrate_project_surfaces(dry_run=False, analysis_only=False)
            second_report = MODULE.migrate_project_surfaces(dry_run=False, analysis_only=False)
            payload = json.loads((root / ".codex" / "hooks.json").read_text(encoding="utf-8"))

        self.assertEqual(payload["_generated_by"], MODULE.GENERATED_HOOKS_MARKER)
        self.assertTrue(first_report.generated_artifacts)
        self.assertFalse(
            any(item["status"] == "target-collision" for item in second_report.unsupported_hooks)
        )
        self.assertEqual(second_report.generated_artifacts, [".codex/hooks.json"])

    def test_invalid_settings_json_reports_without_writing(self) -> None:
        with temporary_repo({}, settings_files={"settings.json": "{not json"}) as root:
            report = MODULE.migrate_project_surfaces(dry_run=False, analysis_only=False)

        self.assertFalse((root / ".codex" / "hooks.json").exists())
        self.assertEqual(report.unsupported_hooks[0]["status"], "invalid-source-json")

    def test_existing_user_hooks_json_blocks_live_write(self) -> None:
        with temporary_repo(
            {},
            settings_files={
                "settings.json": json.dumps(
                    {"hooks": {"Stop": [{"hooks": [{"command": "npm test"}]}]}}
                )
            },
            existing_hooks_json='{"hooks": {}}\n',
        ) as root:
            report = MODULE.migrate_project_surfaces(dry_run=False, analysis_only=False)
            text = (root / ".codex" / "hooks.json").read_text(encoding="utf-8")

        self.assertEqual(text, '{"hooks": {}}\n')
        self.assertNotIn(MODULE.GENERATED_HOOKS_MARKER, text)
        self.assertTrue(any(item["status"] == "target-collision" for item in report.unsupported_hooks))


class ProjectSurfaceFlowTests(unittest.TestCase):
    def test_single_skill_mode_does_not_convert_commands_or_hooks(self) -> None:
        skill_packages = {"example-skill": {"SKILL.md": make_skill("# Example")}}
        with temporary_repo(
            skill_packages,
            command_files={"deploy.md": "Deploy\n"},
            settings_files={
                "settings.json": json.dumps(
                    {"hooks": {"Stop": [{"hooks": [{"command": "npm test"}]}]}}
                )
            },
        ) as root:
            MODULE.migrate_skill("example-skill", dry_run=False, analysis_only=False, emit_text=False)

        self.assertFalse((root / ".codex" / "skills" / "command-deploy").exists())
        self.assertFalse((root / ".codex" / "hooks.json").exists())

    def test_analysis_only_reports_commands_and_hooks_without_writing(self) -> None:
        with temporary_repo(
            {},
            command_files={"deploy.md": "Deploy\n"},
            settings_files={
                "settings.json": json.dumps(
                    {"hooks": {"Stop": [{"hooks": [{"command": "npm test"}]}]}}
                )
            },
        ) as root:
            stdout = io.StringIO()
            original_argv = sys.argv
            try:
                sys.argv = [
                    "migrate_claude_workflows_to_codex.py",
                    "--analysis-only",
                    "--json",
                ]
                with contextlib.redirect_stdout(stdout):
                    exit_code = MODULE.main()
            finally:
                sys.argv = original_argv

            payload = json.loads(stdout.getvalue())

        self.assertEqual(exit_code, 0)
        self.assertEqual(payload["summary"]["commands_discovered"], 1)
        self.assertEqual(payload["summary"]["manual_review_items"], 2)
        self.assertEqual(payload["summary"]["hook_entries_generated"], 1)
        self.assertFalse((root / ".codex" / "skills" / "command-deploy").exists())
        self.assertFalse((root / ".codex" / "hooks.json").exists())

    def test_dry_run_reports_commands_and_hooks_without_writing(self) -> None:
        with temporary_repo(
            {},
            command_files={"deploy.md": "Deploy\n"},
            settings_files={
                "settings.json": json.dumps(
                    {"hooks": {"Stop": [{"hooks": [{"command": "npm test"}]}]}}
                )
            },
        ) as root:
            stdout = io.StringIO()
            original_argv = sys.argv
            try:
                sys.argv = ["migrate_claude_workflows_to_codex.py", "--dry-run", "--json"]
                with contextlib.redirect_stdout(stdout):
                    MODULE.main()
            finally:
                sys.argv = original_argv

        self.assertFalse((root / ".codex" / "skills" / "command-deploy").exists())
        self.assertFalse((root / ".codex" / "hooks.json").exists())

    def test_live_batch_generates_outputs(self) -> None:
        with temporary_repo(
            {},
            command_files={"deploy.md": "Deploy\n"},
            settings_files={
                "settings.json": json.dumps(
                    {"hooks": {"Stop": [{"hooks": [{"command": "npm test"}]}]}}
                )
            },
        ) as root:
            stdout = io.StringIO()
            original_argv = sys.argv
            try:
                sys.argv = ["migrate_claude_workflows_to_codex.py", "--json"]
                with contextlib.redirect_stdout(stdout):
                    MODULE.main()
            finally:
                sys.argv = original_argv

            self.assertTrue(
                (root / ".codex" / "skills" / "command-deploy" / "SKILL.md").exists()
            )
            self.assertTrue((root / ".codex" / "hooks.json").exists())


